import { StrictMode } from "react"
import { createRoot } from "react-dom/client"
import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { createRouter, RouterProvider } from "@tanstack/react-router"

import "./index.css"
// Generated by @tanstack/router-plugin from the files in src/routes — don't edit by hand.
import { routeTree } from "./routeTree.gen"

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000, // treat data as fresh for 30s → fewer refetches
      retry: 1,
    },
  },
})

const router = createRouter({
  routeTree,
  basepath: import.meta.env.BASE_URL, // "/" in dev, "/<repo>/" on GitHub Pages
  context: { queryClient }, // available in every route's loader as `context.queryClient`
  defaultPreload: "intent", // hover a <Link> → its loader starts
  defaultPreloadStaleTime: 0, // let TanStack Query own caching, not the router
  scrollRestoration: true,
})

// Registers the router type globally → typesafe <Link to>, params and search everywhere.
declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router
  }
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  </StrictMode>,
)
